"""Word Search II — one trie of all words, walked alongside the DFS.

Searching every word separately re-explores the board; the trie shares prefixes
so the board is traversed once. Matched nodes are pruned to keep the trie small.

Time: O(m * n * 4^L)   Space: O(total characters)
"""
from typing import List


class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        trie = {}
        for word in words:
            node = trie
            for ch in word:
                node = node.setdefault(ch, {})
            node["$"] = word

        m, n = len(board), len(board[0])
        found = []

        def walk(i: int, j: int, node: dict) -> None:
            ch = board[i][j]
            nxt = node.get(ch)
            if nxt is None:
                return
            word = nxt.pop("$", None)
            if word:
                found.append(word)
            board[i][j] = "#"
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                x, y = i + di, j + dj
                if 0 <= x < m and 0 <= y < n and board[x][y] != "#":
                    walk(x, y, nxt)
            board[i][j] = ch
            if not nxt:
                node.pop(ch)          # dead branch, never visit it again

        for i in range(m):
            for j in range(n):
                walk(i, j, trie)
        return found
